// src/skill-events.ts
var SAFE_TEXT_MAX2 = 512;
var SAFE_PATH_MAX2 = 2048;
var safeString2 = (label2, max = SAFE_TEXT_MAX2) => external_exports.string().trim().min(1, `${label2} is required`).max(max, `${label2} is too large`);
var SKILL_EVENT_TYPES = ["viewed", "used", "result", "changed", "patched"];
var SKILL_RESULT_STATUSES = [
  "succeeded",
  "failed",
  "abandoned",
  "blocked",
  "unknown"
];
var resultSchema = external_exports.object({
  status: external_exports.enum(SKILL_RESULT_STATUSES),
  duration_ms: external_exports.number().int().nonnegative().max(864e5).optional(),
  error_class: safeString2("error_class", 160).optional(),
  error_code: safeString2("error_code", 160).optional(),
  error_stage: safeString2("error_stage", 160).optional()
}).strict();
var eventSchema = external_exports.object({
  event_type: external_exports.enum(SKILL_EVENT_TYPES),
  event_id: safeString2("event_id", 200),
  timestamp: external_exports.string().datetime({ offset: true }).or(external_exports.string().datetime({ offset: false })),
  session_id: safeString2("session_id", 200),
  turn_id: safeString2("turn_id", 200),
  name: safeString2("name", 200),
  source_kind: safeString2("source_kind", 80),
  path: safeString2("path", SAFE_PATH_MAX2),
  runner: safeString2("runner", 80),
  result: resultSchema.optional()
}).strict().superRefine((event, ctx) => {
  if (event.event_type === "result" && !event.result) {
    ctx.addIssue({
      code: external_exports.ZodIssueCode.custom,
      path: ["result"],
      message: "result events require a safe result payload"
    });
  }
  if (event.event_type !== "result" && event.result) {
    ctx.addIssue({
      code: external_exports.ZodIssueCode.custom,
      path: ["result"],
      message: "result payloads are only valid on result events"
    });
  }
});
async function readSkillRollups(store) {
  const rollups = await readSkillRollupMap(store);
  return Object.values(rollups).sort((a, b) => a.name.localeCompare(b.name));
}
async function readSkillRollupMap(store) {
  const rollups = {};
  const nodes = await store.listNodes();
  for (const node of nodes) {
    const skill = node.properties?.skill;
    if (!isStoredSkill(skill)) continue;
    const stored = await store.kvGet(skillRollupStorageKey(skill));
    if (stored == null) continue;
    rollups[skillRollupKey(skill)] = parseKvValue(stored);
  }
  return rollups;
}
function parseKvValue(raw) {
  return typeof raw === "string" ? JSON.parse(raw) : raw;
}
function skillRollupKey(skill) {
  return `${skill.source_kind}:${skill.name}:${skill.path}`;
}
function skillRollupStorageKey(skill) {
  return `skill-rollup:${contentHash(skill.source_kind, skill.name, skill.path)}`;
}
function isStoredSkill(input) {
  if (input == null || typeof input !== "object") return false;
  const value = input;
  return typeof value.source_kind === "string" && typeof value.name === "string" && typeof value.path === "string";
}

// src/memory-health.ts
var DEFAULT_ENGINE_EVENT_WINDOW_MS = 24 * 60 * 60 * 1e3;
async function buildMemoryHealthReport(store, input = {}) {
  const [stats, vector, stale, rollups, engineEvents] = await Promise.all([
    store.stats(),
    vectorHealth(store),
    diagnose(store, { staleDays: input.stale_days }),
    skillTelemetryHealth(store),
    engineEventHealth(store, input)
  ]);
  const actions = healthActions(vector, stale, rollups);
  return {
    schema_version: "memory.health.v1",
    read_only: true,
    state: vector.overall === "failed" || rollups.status === "unavailable" ? "degraded" : actions.length > 0 ? "attention" : "ready",
    stats,
    vector,
    stale: {
      total: stale.totalNodes,
      stale: stale.stale.length
    },
    skill_telemetry: rollups,
    engine_events: engineEvents,
    recommended_next_actions: actions.length > 0 ? actions : ["memory graph is ready for agent use"]
  };
}
async function engineEventHealth(store, input = {}) {
  const windowMs = input.engine_events_window_ms == null ? DEFAULT_ENGINE_EVENT_WINDOW_MS : input.engine_events_window_ms;
  const useWindow = Number.isFinite(windowMs) && windowMs > 0;
  try {
    const events = await readMemoryEvents(store, {
      retentionMs: useWindow ? windowMs : void 0,
      now: input.now
    });
    return {
      status: "available",
      window_ms: useWindow ? windowMs : 0,
      ...aggregateEngineEvents(events)
    };
  } catch (err) {
    return {
      status: "unavailable",
      window_ms: useWindow ? windowMs : 0,
      total: 0,
      writes_by_layer: {},
      recall_hit_rate: 0,
      recall_total: 0,
      recall_hits: 0,
      promotion_count: 0,
      eviction_count: 0,
      conflict_count: 0,
      error: err instanceof Error ? err.message : String(err)
    };
  }
}
function aggregateEngineEvents(events) {
  const writesByLayer = {};
  let recallTotal = 0;
  let recallHits = 0;
  let promotionCount = 0;
  let evictionCount = 0;
  let conflictCount = 0;
  let total = 0;
  for (const event of events) {
    if (event.kind !== "engine.op") continue;
    const payload = event.payload;
    total++;
    switch (payload.op) {
      case "store": {
        const layer = payload.layer ?? "L3";
        writesByLayer[layer] = (writesByLayer[layer] ?? 0) + 1;
        break;
      }
      case "recall":
        recallTotal++;
        if (payload.outcome === "hit") recallHits++;
        break;
      case "promote":
        promotionCount++;
        break;
      case "evict":
        evictionCount++;
        break;
      case "conflict-detected":
        conflictCount++;
        break;
    }
  }
  return {
    total,
    writes_by_layer: writesByLayer,
    recall_hit_rate: recallTotal === 0 ? 0 : recallHits / recallTotal,
    recall_total: recallTotal,
    recall_hits: recallHits,
    promotion_count: promotionCount,
    eviction_count: evictionCount,
    conflict_count: conflictCount
  };
}
async function vectorHealth(store) {
  try {
    const vector = await store.vectorStatus();
    return {
      overall: vector.overall,
      total: vector.total,
      ready: vector.ready,
      stale: vector.stale,
      unavailable: vector.unavailable,
      failed: vector.failed
    };
  } catch (err) {
    return {
      overall: "unavailable",
      total: 0,
      ready: 0,
      stale: 0,
      unavailable: 0,
      failed: 0,
      error: err instanceof Error ? err.message : String(err)
    };
  }
}
async function skillTelemetryHealth(store) {
  try {
    return { status: "available", rollups: (await readSkillRollups(store)).length };
  } catch (err) {
    return {
      status: "unavailable",
      rollups: 0,
      error: err instanceof Error ? err.message : String(err)
    };
  }
}
function healthActions(vector, stale, rollups) {
  const actions = [];
  if (vector.overall === "stale" || vector.stale > 0) {
    actions.push("refresh vector projections before relying on semantic recall");
  }
  if (vector.overall === "failed" || vector.failed > 0) {
    actions.push("repair failed vector projections");
  }
  if (stale.stale.length > 0) {
    actions.push("review stale Memory nodes before using old guidance");
  }
  if (rollups.status === "unavailable" || rollups.rollups === 0) {
    actions.push("collect Skill telemetry before relying on skill evolution signals");
  }
  return actions;
}

