async function resolveStore() {
  if (process.env.RED_MEMORY_URI) {
    return {
      uri: process.env.RED_MEMORY_URI,
      project: process.env.RED_MEMORY_PROJECT ?? basename(process.cwd()),
      root: process.env.MEMORY_ROOT ?? process.cwd()
    };
  }
  const root = process.env.MEMORY_ROOT ?? process.cwd();
  const config2 = await readConfig(root);
  if (!config2) {
    throw new Error(
      `memory is not initialized at ${root} \u2014 run \`memory init --mode graph\` first (or set RED_MEMORY_URI)`
    );
  }
  if (config2.mode !== "graph") {
    throw new Error(
      `the MCP server needs graph mode \u2014 ${root} is "${config2.mode}". Re-run \`memory init --mode graph\``
    );
  }
  return {
    uri: resolveStoreUri(root, config2),
    project: process.env.RED_MEMORY_PROJECT ?? basename(root),
    root
  };
}
